"""Payment signature verification module for K8s payment gateway.
Handles HMAC-based transaction integrity verification."""

import hmac
import hashlib
import time
import json
import os
from dataclasses import dataclass, field
from typing import Optional, Dict, List
from decimal import Decimal, ROUND_DOWN

# K8s secret mounted at runtime
SIGNING_KEY = os.environ.get('PAYMENT_SIGNING_KEY', '').encode('utf-8')
REPLAY_WINDOW_SECONDS = 300

_nonce_store: Dict[str, float] = {}


@dataclass
class PaymentRequest:
    merchant_id: str
    amount: str  # String to preserve decimal precision
    currency: str
    nonce: str
    timestamp: int
    items: List[Dict[str, str]] = field(default_factory=list)
    discount_code: Optional[str] = None
    signature: str = ""


def _canonicalize_amount(amount_str: str) -> str:
    """Canonicalize amount to 2 decimal places for signing."""
    d = Decimal(amount_str).quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    return str(d)


def _compute_items_total(items: List[Dict[str, str]]) -> Decimal:
    """Compute total from individual line items."""
    total = Decimal('0.00')
    for item in items:
        price = Decimal(item.get('price', '0'))
        quantity = int(item.get('quantity', '1'))
        total += price * quantity
    return total.quantize(Decimal('0.01'), rounding=ROUND_DOWN)


def _apply_discount(total: Decimal, discount_code: Optional[str]) -> Decimal:
    """Apply discount code if valid. Returns discounted total."""
    if not discount_code:
        return total
    # Discount codes: SAVE10 = 10%, SAVE20 = 20%, max 50% off
    discount_map = {'SAVE10': Decimal('0.10'), 'SAVE20': Decimal('0.20')}
    rate = discount_map.get(discount_code.upper(), Decimal('0'))
    discounted = total * (Decimal('1') - rate)
    return discounted.quantize(Decimal('0.01'), rounding=ROUND_DOWN)


def _build_signing_payload(request: PaymentRequest) -> bytes:
    """Build the canonical payload for HMAC signing.

    The signing payload includes merchant_id, canonical amount, currency,
    nonce, timestamp, and discount_code to prevent tampering.
    """
    canonical_amount = _canonicalize_amount(request.amount)
    payload_parts = [
        request.merchant_id,
        canonical_amount,
        request.currency,
        request.nonce,
        str(request.timestamp),
        request.discount_code or ''
    ]
    return "|".join(payload_parts).encode('utf-8')


def _verify_signature(request: PaymentRequest) -> bool:
    """Verify HMAC-SHA256 signature of the payment request."""
    if not SIGNING_KEY:
        raise ValueError("Signing key not configured")

    expected_payload = _build_signing_payload(request)
    expected_sig = hmac.new(SIGNING_KEY, expected_payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, request.signature)


def _check_replay(nonce: str, timestamp: int) -> bool:
    """Check for replay attacks using nonce and timestamp window."""
    current_time = int(time.time())
    if abs(current_time - timestamp) > REPLAY_WINDOW_SECONDS:
        return False
    if nonce in _nonce_store:
        return False
    _nonce_store[nonce] = time.time()
    # Cleanup old nonces
    cutoff = time.time() - REPLAY_WINDOW_SECONDS * 2
    expired = [k for k, v in _nonce_store.items() if v < cutoff]
    for k in expired:
        del _nonce_store[k]
    return True


def _validate_amount_consistency(request: PaymentRequest) -> bool:
    """Validate that the stated amount matches computed items total.

    This prevents amount manipulation where the signed amount
    differs from what the items actually cost.
    """
    if not request.items:
        return True  # No items to validate against

    items_total = _compute_items_total(request.items)
    discounted_total = _apply_discount(items_total, request.discount_code)
    stated_amount = Decimal(_canonicalize_amount(request.amount))

    # Allow small rounding tolerance
    return abs(discounted_total - stated_amount) <= Decimal('0.01')


def process_payment(raw_request: dict) -> dict:
    """Main payment processing entry point.

    Validates signature, checks replay, verifies amount consistency,
    then processes the payment.
    """
    try:
        request = PaymentRequest(
            merchant_id=raw_request['merchant_id'],
            amount=raw_request['amount'],
            currency=raw_request['currency'],
            nonce=raw_request['nonce'],
            timestamp=raw_request['timestamp'],
            items=raw_request.get('items', []),
            discount_code=raw_request.get('discount_code'),
            signature=raw_request['signature']
        )
    except (KeyError, TypeError) as e:
        return {'status': 'error', 'message': f'Invalid request format: {e}'}

    # Step 1: Verify cryptographic signature
    try:
        if not _verify_signature(request):
            return {'status': 'error', 'message': 'Invalid signature'}
    except Exception as e:
        return {'status': 'error', 'message': f'Signature verification failed: {e}'}

    # Step 2: Check for replay attacks
    if not _check_replay(request.nonce, request.timestamp):
        return {'status': 'error', 'message': 'Replay detected or expired timestamp'}

    # Step 3: Validate amount consistency
    if not _validate_amount_consistency(request):
        return {'status': 'error', 'message': 'Amount mismatch with items'}

    # Step 4: Process the payment - charge the signed amount
    charge_amount = Decimal(_canonicalize_amount(request.amount))

    return {
        'status': 'success',
        'charged_amount': str(charge_amount),
        'currency': request.currency,
        'merchant_id': request.merchant_id,
        'transaction_id': f'txn_{request.nonce}'
    }
